// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address sender) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.assume(sender != address(0));
        vm.assume(sender.code.length == 0);

        uint256 prevBalance = c.getBalance(sender);
        vm.deal(sender, amount);
        vm.prank(sender);
        c.addToBalance{value: amount}();
        uint256 newBalance = c.getBalance(sender);

        uint256 expected = prevBalance + amount;
        assertTrue(newBalance == expected);
    }
}
